/* @autogenerated */
import { Component, Input, signal } from '@angular/core';
import { TestBed } from '@angular/core/testing';
import { BreakpointObserver, Breakpoints } from '@angular/cdk/layout';
import { of } from 'rxjs';
import { ActionContainerComponent } from './action-container.component';
import { LocalRouteStateService } from '@shared/interaction/local-route-state/local-route-state.service';

class MockBreakpointObserver {
  observe() {
    return of({
      matches: false,
      breakpoints: {
        [Breakpoints.XLarge]: false,
        [Breakpoints.Large]: false,
        [Breakpoints.Medium]: false,
        [Breakpoints.Small]: false,
        [Breakpoints.XSmall]: false,
      },
    });
  }
}

class MockLocalRouteStateService {
  bind() {
    return {
      watch: () => of({}),
      go: jasmine.createSpy('go'),
    };
  }
}

/** Acción mínima: siempre visible y habilitada. */
@Component({ selector: 'fake-action', standalone: true, template: '' })
class FakeActionComponent {
  @Input() name = '';
  @Input() contextual = false;
  @Input() multiple = false;
  default = signal(false);
  label = signal('');
  icon = signal('');
  tooltip = signal('');
  title = signal('');
  container = signal<any>(undefined);
  selection = signal<any[]>([]);
  render = signal(undefined);
  visible = () => signal(true);
  enabled = () => signal(true);
  run() {}
}

@Component({
  standalone: true,
  imports: [ActionContainerComponent, FakeActionComponent],
  template: `
    <action-container #container [maxIcons]="2">
      <fake-action #action name="create" />
      <fake-action #action name="import" />
      <fake-action #action name="export" [multiple]="true" />
      <fake-action #action name="edit" [contextual]="true" />
      <fake-action #action name="deleteSelection" [contextual]="true" [multiple]="true" />
    </action-container>
  `,
})
class HostComponent {}

describe('ActionContainerComponent', () => {
  afterEach(() => TestBed.resetTestingModule());

  it('tracks selection state', () => {
    TestBed.configureTestingModule({
      imports: [ActionContainerComponent],
      providers: [{ provide: BreakpointObserver, useClass: MockBreakpointObserver }],
    });
    // El servicio se provee en el propio componente
    TestBed.overrideProvider(LocalRouteStateService, { useValue: new MockLocalRouteStateService() });

    const fixture = TestBed.createComponent(ActionContainerComponent);
    const component = fixture.componentInstance;

    expect(component.hasSelection()).toBeFalse();

    component.selectionModel.select([{ id: 1 }]);
    expect(component.hasSelection()).toBeTrue();
  });

  it('moves the general actions that do not fit into the toolbar menu and offers the multiple ones on a selection', () => {
    TestBed.configureTestingModule({
      imports: [HostComponent],
      providers: [{ provide: BreakpointObserver, useClass: MockBreakpointObserver }],
    });
    TestBed.overrideProvider(LocalRouteStateService, { useValue: new MockLocalRouteStateService() });

    const fixture = TestBed.createComponent(HostComponent);
    fixture.detectChanges();
    const container = fixture.debugElement.children[0].componentInstance as ActionContainerComponent;
    const names = (actions: { name: string }[]) => actions.map((action) => action.name);

    expect(names(container.toolbarActions())).toEqual(['create', 'import']);
    expect(names(container.toolbarMenu())).toEqual(['export']);
    // Exportar es general pero también admite selección: va en la barra de selección, no en cada fila
    expect(names(container.multipleActions())).toEqual(['export', 'deleteSelection']);
    expect(names(container.contextualActions())).toEqual(['edit', 'deleteSelection']);
  });
});
